  'REFUNDED': 'accent',
  'UNSUBMITTED': 'textSecondary',
  'NOT_SUBMITTED': 'textSecondary',
};

/// Resolve a domain status string to its colour in the active theme.
/// Unknown statuses fall back to secondary text rather than to a colour that
/// would assert a meaning the system does not have.
Color statusColor(String status, DesignTokens t) {
  switch (kStatusRole[status.toUpperCase()]) {
    case 'success':
      return t.success;
    case 'warning':
      return t.warning;
    case 'critical':
      return t.critical;
    case 'review':
      return t.review;
    case 'accent':
      return t.accent;
    default:
      return t.textSecondary;
  }
}

/// The on-light text/icon colour for a status. Never use [statusColor] as text
/// on a light surface: a status 500 is a fill hue and most of them sit under
/// 3:1 on white.
Color statusInk(String status, DesignTokens t) {
  switch (kStatusRole[status.toUpperCase()]) {
    case 'success':
      return t.successInk;
    case 'warning':
      return t.warningInk;
    case 'critical':
      return t.criticalInk;
    case 'review':
      return t.reviewInk;
    case 'accent':
      return t.accentInk;
    default:
      return t.textSecondary;
  }
}

/// Spacing scale — 8px, with a single 4px sub-step for icon-label gaps only
class DesignSpace {
  DesignSpace._();

  static const double hair = 4;
  static const double xs = 8;
  static const double sm = 12;
  static const double md = 16;
  static const double lg = 24;
  static const double xl = 32;
  static const double xxl = 48;
  static const double huge = 64;
}

/// Radius scale — 6px hard cap, 'machined edges not lozenges'
class DesignRadius {
  DesignRadius._();

  static const double input = 2;
  static const double button = 4;
  static const double card = 6;
  static const double circle = 999;
}

/// Motion scale — shared with the web surfaces so the same gesture
/// decelerates identically everywhere.
class DesignMotion {
  DesignMotion._();

  static const Duration fast = Duration(milliseconds: 160);
  static const Duration base = Duration(milliseconds: 260);
  static const Duration slow = Duration(milliseconds: 420);
  static const Curve ease = Cubic(0.16, 1, 0.3, 1);
}
